<script lang="ts">
  import { onMount } from 'svelte';
  import { afterNavigate } from '$app/navigation';
  import { attendanceSessionStatus, attendanceLatenessLabel, attendanceDurationReview } from '#lib/attendance-status';
  import { app, actions, isAdmin, isCashier, displayName, shiftLabel, attendancePermission, attendanceLateStatus } from '#lib/state/app';
  import type { AttendanceRecord, AttendanceCorrectionRequest, Shift, LeaveRequest, AuditEntry } from '#lib/types';
  import PageHeading from '#lib/components/PageHeading.svelte';
  import Icon from '#lib/components/Icon.svelte';
  import MetricCard from '#lib/components/MetricCard.svelte';
  import StatusPill from '#lib/components/StatusPill.svelte';
  import EmptyState from '#lib/components/EmptyState.svelte';
  import Modal from '#lib/components/Modal.svelte';
  import Feedback from '#lib/components/Feedback.svelte';
  import { dateLabel, timeLabel, durationLabel, todayJakarta, leaveTypeLabel, leaveStatusLabel, leaveTone } from '#lib/components/format';
  let tab: 'attendance' | 'leave' | 'audit' = 'attendance', start = '', end = '', outletId = '', search = '', message = '', failed = false, saving = false;
  let selected: AttendanceRecord | null = null, correctedIn = '', correctedOut = '', correctedShift: Shift = 'morning', reason = '';
  let now = Date.now(), auditEntityId = '', sessionFilter: 'all' | 'open' | 'review' = 'all';
  afterNavigate(() => {
    const query = new URLSearchParams(window.location.search), requestedTab = query.get('tab');
    if (requestedTab === 'attendance' || requestedTab === 'leave' || requestedTab === 'audit') tab = requestedTab;
    auditEntityId = query.get('entity') ?? ''; linkedCorrectionId = query.get('correction') ?? query.get('request') ?? ''; if (requestedTab === 'corrections') tab = 'attendance';
  });
  const lateText = (record: AttendanceRecord) => attendanceLatenessLabel(attendanceLateStatus(record));
  const lateTone = (record: AttendanceRecord): 'amber' | 'blue' | 'green' => attendanceLateStatus(record).unexcusedMinutes > 0 ? 'amber' : attendanceLateStatus(record).permittedMinutes > 0 ? 'blue' : 'green';
  onMount(() => {
    const updateNow = () => { now = Date.now(); };
    const interval = window.setInterval(updateNow, 30_000);
    window.addEventListener('focus', updateNow); document.addEventListener('visibilitychange', updateNow); updateNow();
    return () => { window.clearInterval(interval); window.removeEventListener('focus', updateNow); document.removeEventListener('visibilitychange', updateNow); };
  });
  let correctionReview: AttendanceCorrectionRequest | null = null, correctionNote = '', linkedCorrectionId = '', handledCorrectionId = '';
  $: correctionRequests = ($app.attendanceCorrectionRequests ?? []).slice().sort((a,b) => b.createdAt.localeCompare(a.createdAt));
  $: if (linkedCorrectionId && linkedCorrectionId !== handledCorrectionId && $app.initialized) { const request = correctionRequests.find(request => request.id === linkedCorrectionId); if (request) { correctionReview = request; correctionNote = ''; handledCorrectionId = linkedCorrectionId; } }
  async function decideCorrection(approved: boolean) { if (!correctionReview || saving) return; saving = true; try { if (correctionNote.trim().length < 3) throw new Error('Isi alasan keputusan dan sumber konfirmasi, minimal 3 karakter.'); await actions.decideAttendanceCorrection(correctionReview.id, approved, correctionNote.trim()); correctionReview = null; failed = false; message = approved ? 'Koreksi disetujui dan catatan absensi diperbarui secara utuh.' : 'Koreksi ditolak. Catatan asli dipertahankan.'; } catch(error) { failed = true; message = error instanceof Error ? error.message : 'Keputusan belum tersimpan.'; } finally { saving = false; } }
  let manualOpen = false, manualEmployeeId = '', manualShift: Shift = 'morning', manualIn = '', manualOut = '', manualReason = '';
  $: admin = isAdmin($app.user ?? undefined);
  $: manualCashiers = $app.employees.filter((employee) => employee.status === 'active' && employee.id !== $app.user?.id && isCashier(employee));
  $: manualEmployee = manualCashiers.find((employee) => employee.id === manualEmployeeId);
  $: if (manualShift === 'middle' && !manualEmployee?.canMiddleShift) manualShift = 'morning';
  const jakartaDate = (value: string) => new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Jakarta', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date(value));
  const matchDate = (value: string) => (!start || value >= start) && (!end || value <= end);
  const matchEmployee = (id: string) => { const employee = $app.employees.find((e) => e.id === id); return (!search || `${employee?.fullName} ${employee?.employeeNumber}`.toLowerCase().includes(search.toLowerCase())) && (!outletId || employee?.outletId === outletId); };
  $: attendance = filterAttendance($app.attendanceRecords, start, end, outletId, search).filter(record => sessionFilter === 'all' || (sessionFilter === 'open' ? !record.clockOut : ['stale','review'].includes(attendanceSessionStatus(record, now))));
  $: lateness = attendance.map(record => attendanceLateStatus(record));
  $: leaves = filterLeaves($app.leaveRequests, start, end, outletId, search);
  $: audits = filterAudits($app.auditEntries, start, end, outletId, search).filter(entry => !auditEntityId || entry.entityId === auditEntityId);
  function filterAttendance(records: AttendanceRecord[], from: string, until: string, outlet: string, query: string) { return records.filter((r) => (!from || jakartaDate(r.clockIn) >= from) && (!until || jakartaDate(r.clockIn) <= until) && (!outlet || r.outletId === outlet) && (!query || `${displayName(r.employeeId)} ${employeeNumber(r.employeeId)}`.toLowerCase().includes(query.toLowerCase()))).slice().sort((a, b) => b.clockIn.localeCompare(a.clockIn)); }
  function filterLeaves(records: LeaveRequest[], from: string, until: string, outlet: string, query: string) { return records.filter((r) => (!from || r.endDate >= from) && (!until || r.startDate <= until) && matchesEmployee(r.employeeId, outlet, query)).slice().sort((a, b) => b.createdAt.localeCompare(a.createdAt)); }
  function filterAudits(records: AuditEntry[], from: string, until: string, outlet: string, query: string) { return records.filter((r) => (!from || jakartaDate(r.at) >= from) && (!until || jakartaDate(r.at) <= until) && matchesEmployee(r.actorId, outlet, query)).slice().sort((a, b) => b.at.localeCompare(a.at)); }
  function matchesEmployee(id: string, outlet: string, query: string) { const employee = $app.employees.find((e) => e.id === id); return (!outlet || employee?.outletId === outlet) && (!query || `${employee?.fullName ?? ''} ${employee?.employeeNumber ?? ''}`.toLowerCase().includes(query.toLowerCase())); }
  const outletName = (id: string) => $app.outlets.find((o) => o.id === id)?.name || '—';
  const employeeNumber = (id: string) => $app.employees.find((e) => e.id === id)?.employeeNumber || '';
  function localInput(value: string | null) { if (!value) return ''; const date = new Date(value); const parts = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Jakarta', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).formatToParts(date); const get = (key: string) => parts.find((p) => p.type === key)?.value || ''; return `${get('year')}-${get('month')}-${get('day')}T${get('hour')}:${get('minute')}`; }
  function openCorrection(record: AttendanceRecord) { if (record.employeeId === $app.user?.id) return; selected = record; correctedIn = localInput(record.clockIn); correctedOut = localInput(record.clockOut); correctedShift = record.shift; reason = ''; message = ''; failed = false; }
  function openManual() { manualEmployeeId = ''; manualShift = 'morning'; manualIn = ''; manualOut = ''; manualReason = ''; message = ''; failed = false; manualOpen = true; }
  async function saveManual() {
    saving = true; message = '';
    try {
      if (!manualEmployee) throw new Error('Pilih kasir aktif selain diri sendiri.');
      if (!manualReason.trim()) throw new Error('Alasan dan sumber konfirmasi wajib diisi.');
      const clockIn = new Date(`${manualIn}:00+07:00`).toISOString();
      const clockOut = manualOut ? new Date(`${manualOut}:00+07:00`).toISOString() : null;
      await actions.recordManualAttendance({ employeeId: manualEmployeeId, shift: manualShift, clockIn, clockOut, reason: manualReason.trim() });
      manualOpen = false; failed = false; message = 'Absensi manual tersimpan. Catatan ditandai tanpa verifikasi GPS dan selfie.';
    } catch (error) { failed = true; message = error instanceof Error ? error.message : 'Absensi manual belum berhasil disimpan.'; }
    finally { saving = false; }
  }
  async function saveCorrection() { if (!selected) return; saving = true; message = ''; try { const clockIn = new Date(`${correctedIn}:00+07:00`).toISOString(); const clockOut = correctedOut ? new Date(`${correctedOut}:00+07:00`).toISOString() : null; if (clockOut && clockOut < clockIn) throw new Error('Waktu pulang harus setelah waktu masuk.'); await actions.correctAttendance(selected.id, { clockIn, clockOut, shift: correctedShift, reason }); selected = null; failed = false; message = 'Koreksi berhasil disimpan. Catatan asli dan alasan tersimpan dalam riwayat.'; } catch (error) { failed = true; message = error instanceof Error ? error.message : 'Koreksi belum berhasil disimpan.'; } finally { saving = false; } }
  function exportCsv() { let data: (string | number | null)[][]; if (tab === 'attendance') data = [['Nomor Karyawan', 'Nama', 'Outlet', 'Tanggal', 'Shift', 'Clock In WIB', 'Clock Out WIB', 'Durasi Aktual Menit', 'Selisih Target 480 Menit', 'Selisih Berizin Menit', 'Selisih Perlu Penjelasan Menit', 'Konteks Izin Keluar (Bukan Jam Aktual)', 'Keterlambatan Aktual Menit', 'Keterlambatan Berizin Menit', 'Keterlambatan Tanpa Izin Menit', 'Status Keterlambatan', 'Status Sesi', 'Jarak Masuk Meter', 'Jarak Pulang Meter', 'Sumber Pencatatan', 'Verifikasi GPS dan Selfie', 'Izin Datang Terlambat', 'Dikoreksi', 'Alasan Koreksi atau Pencatatan Manual'], ...attendance.map((r) => [employeeNumber(r.employeeId), displayName(r.employeeId), outletName(r.outletId), jakartaDate(r.clockIn), shiftLabel(r.shift), timeLabel(r.clockIn), timeLabel(r.clockOut), r.durationMinutes, attendanceDurationReview(r,$app.leaveRequests).shortfallMinutes, attendanceDurationReview(r,$app.leaveRequests).permittedMinutes, attendanceDurationReview(r,$app.leaveRequests).unexplainedMinutes, attendanceDurationReview(r,$app.leaveRequests).temporaryExit.join('; '), r.lateMinutes, attendanceLateStatus(r).permittedMinutes, attendanceLateStatus(r).unexcusedMinutes, lateText(r), ['stale','review'].includes(attendanceSessionStatus(r, now)) ? 'Perlu diperiksa (durasi 12 jam atau lebih)' : !r.clockOut ? 'Belum clock out' : 'Selesai', r.inDistance == null ? null : Math.round(r.inDistance), r.outDistance == null ? null : Math.round(r.outDistance), r.source === 'manual' ? 'Manual HR' : 'Perangkat', r.source === 'manual' ? 'Tidak diverifikasi GPS maupun selfie' : 'Bukti lokasi dan selfie saat clock in', attendancePermission(r), r.corrected ? 'Ya' : 'Tidak', r.correctionReason])]; else if (tab === 'leave') data = [['Nomor Karyawan', 'Nama', 'Jenis', 'Tanggal Mulai', 'Tanggal Selesai', 'Jam Mulai', 'Jam Selesai', 'Status', 'Potongan Hari', 'Alasan', 'Pemberi Keputusan', 'Catatan'], ...leaves.map((r) => [employeeNumber(r.employeeId), displayName(r.employeeId), leaveTypeLabel[r.type], r.startDate, r.endDate, r.startTime, r.endTime, leaveStatusLabel[r.status], r.deductionDays, r.reason, r.externalApproverName || (r.approverId ? displayName(r.approverId) : ''), r.note])]; else data = [['Tanggal WIB', 'Pelaku', 'Tindakan', 'ID Data', 'Detail'], ...audits.map((r) => [new Intl.DateTimeFormat('id-ID', { timeZone: 'Asia/Jakarta', dateStyle: 'short', timeStyle: 'short' }).format(new Date(r.at)), displayName(r.actorId), r.action, r.entityId, r.detail])]; const safe = (value: string | number | null) => { let cell = String(value ?? ''); if (/^[\s]*[=+@-]/.test(cell) && typeof value === 'string') cell = `'${cell}`; return `"${cell.replace(/"/g, '""')}"`; }; const csv = '\uFEFF' + data.map((row) => row.map(safe).join(',')).join('\r\n'); const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' })); const link = document.createElement('a'); link.href = url; link.download = `rajaklana-${tab}-${todayJakarta()}.csv`; document.body.appendChild(link); link.click(); link.remove(); window.setTimeout(() => URL.revokeObjectURL(url), 1000); }
</script>

<PageHeading eyebrow="PANTAU & TINJAU" title="Rekap HR" description="Kehadiran, pengajuan, dan riwayat perubahan dalam satu tampilan.">{#if admin}<button class="btn btn-primary" on:click={openManual} disabled={!manualCashiers.length}><Icon name="clock" size={17}/>Catat absensi manual</button><button class="btn btn-secondary" on:click={exportCsv}><Icon name="download" size={17}/>Ekspor CSV</button>{/if}</PageHeading>
{#if !admin}<EmptyState icon="shield" title="Akses khusus Admin HR" description="Riwayat pribadi tersedia pada halaman Kehadiran serta Cuti & izin."/>{:else}
  <div class="metrics"><MetricCard label="Catatan kehadiran" value={attendance.length} detail="Sesuai filter yang dipilih" icon="clock"/><MetricCard label="Terlambat berizin" value={`${lateness.filter(status => status.permittedMinutes > 0).length} catatan`} detail={`${lateness.reduce((total, status) => total + status.permittedMinutes, 0)} menit disetujui`} icon="calendar"/><MetricCard label="Terlambat tanpa izin" value={`${lateness.filter(status => status.unexcusedMinutes > 0).length} catatan`} detail={`${lateness.reduce((total, status) => total + status.unexcusedMinutes, 0)} menit, termasuk lewat izin`} icon="alert"/><MetricCard label="Perlu diperiksa" value={attendance.filter(record => ['stale','review'].includes(attendanceSessionStatus(record, now))).length} detail={`${attendance.filter(record => !record.clockOut).length} belum clock out · sesi panjang tetap ditinjau`} icon="clock" accent/></div>
  <Feedback {message} error={failed}/><section class="panel correction-panel"><h2>Pengajuan koreksi absensi kasir</h2><p class="hint">Tinjau sumber konfirmasi dan waktu aktual. Persetujuan memperbarui catatan dan riwayat dalam satu proses; GPS/selfie yang tidak ada tidak dianggap terverifikasi.</p>{#if correctionRequests.length}<div class="table-wrap"><table><thead><tr><th>Kasir / tanggal</th><th>Usulan waktu aktual</th><th>Status</th><th></th></tr></thead><tbody>{#each correctionRequests as request}<tr><td><strong>{displayName(request.employeeId)}</strong><small>{dateLabel(request.workDate)} · {shiftLabel(request.shift)}</small></td><td>{dateLabel(request.proposedClockIn)} {timeLabel(request.proposedClockIn)}<small>Pulang: {request.proposedClockOut ? `${dateLabel(request.proposedClockOut)} ${timeLabel(request.proposedClockOut)}` : 'masih bekerja'} WIB</small></td><td><StatusPill label={request.status === 'pending' ? 'Menunggu HR' : request.status === 'approved' ? 'Disetujui' : request.status === 'rejected' ? 'Ditolak' : 'Dibatalkan'} tone={request.status === 'approved' ? 'green' : request.status === 'rejected' ? 'red' : 'amber'}/></td><td><button class="btn btn-secondary" on:click={() => { correctionReview = request; correctionNote = ''; }}>Tinjau</button></td></tr>{/each}</tbody></table></div>{:else}<p class="hint">Belum ada pengajuan koreksi dari kasir.</p>{/if}</section><section class="panel report-panel"><div class="tabs" role="tablist" aria-label="Jenis rekap"><button role="tab" aria-selected={tab === 'attendance'} class:active={tab === 'attendance'} on:click={() => tab = 'attendance'}>Kehadiran kasir</button><button role="tab" aria-selected={tab === 'leave'} class:active={tab === 'leave'} on:click={() => tab = 'leave'}>Cuti & izin</button><button role="tab" aria-selected={tab === 'audit'} class:active={tab === 'audit'} on:click={() => tab = 'audit'}>Riwayat perubahan</button></div><div class="filters"><label class="field">Dari tanggal<input class="input" type="date" bind:value={start}/></label><label class="field">Sampai tanggal<input class="input" type="date" bind:value={end} min={start}/></label><label class="field">Outlet<select class="select" bind:value={outletId}><option value="">Semua outlet</option>{#each $app.outlets as outlet}<option value={outlet.id}>{outlet.name}</option>{/each}</select></label><label class="field">Cari karyawan<input class="input" bind:value={search} placeholder="Nama atau nomor…"/></label>{#if tab === 'attendance'}<label class="field">Status sesi<select class="select" bind:value={sessionFilter}><option value="all">Semua sesi</option><option value="open">Belum clock out</option><option value="review">Perlu diperiksa (terbuka/selesai ≥12 jam)</option></select></label>{/if}<button class="reset" on:click={() => { start = ''; end = ''; outletId = ''; search = ''; sessionFilter = 'all'; auditEntityId = ''; }} aria-label="Reset semua filter"><Icon name="refresh" size={17}/></button></div>
    {#if tab === 'audit' && auditEntityId}<div class="audit-filter">Riwayat untuk pengajuan yang dipilih <button class="btn btn-secondary" on:click={() => auditEntityId = ''}>Lihat semua riwayat</button></div>{/if}
    {#if tab === 'attendance'}{#if attendance.length}<div class="table-wrap"><table><thead><tr><th>Karyawan</th><th>Tanggal / shift</th><th>Masuk</th><th>Pulang</th><th>Durasi</th><th>Keterlambatan</th><th>Sumber</th><th></th></tr></thead><tbody>{#each attendance as record}<tr><td><strong>{displayName(record.employeeId)}</strong><small>{employeeNumber(record.employeeId)} · {outletName(record.outletId)}</small></td><td>{dateLabel(record.clockIn)}<small>{shiftLabel(record.shift)}</small></td><td>{timeLabel(record.clockIn)}</td><td>{timeLabel(record.clockOut)}{#if !record.clockOut}<StatusPill label={['stale','review'].includes(attendanceSessionStatus(record, now)) ? 'Perlu diperiksa' : attendanceSessionStatus(record, now) === 'due' ? 'Sudah 8 jam' : 'Berjalan'} tone={['stale','review'].includes(attendanceSessionStatus(record, now)) ? 'amber' : 'blue'}/>{/if}</td><td>{durationLabel(record.durationMinutes)}{#if attendanceDurationReview(record,$app.leaveRequests).shortfallMinutes > 0}<small>Selisih target {attendanceDurationReview(record,$app.leaveRequests).shortfallMinutes} menit</small><small>{attendanceDurationReview(record,$app.leaveRequests).permittedMinutes} menit berizin · {attendanceDurationReview(record,$app.leaveRequests).unexplainedMinutes} perlu penjelasan</small>{/if}{#if attendanceSessionStatus(record,now) === 'review'}<StatusPill label="Perlu diperiksa · ≥12 jam" tone="amber"/>{/if}{#if attendanceDurationReview(record,$app.leaveRequests).temporaryExit.length}<small class="permission-note">Izin keluar {attendanceDurationReview(record,$app.leaveRequests).temporaryExit.join(', ')}. Jam kembali aktual belum dilacak.</small>{/if}</td><td><StatusPill label={lateText(record)} tone={lateTone(record)}/>{#if record.lateMinutes > 0}<small>Aktual {record.lateMinutes} menit</small><small>{attendanceLateStatus(record).permittedMinutes} berizin · {attendanceLateStatus(record).unexcusedMinutes} tanpa izin</small>{/if}{#if attendancePermission(record)}<small class="permission-note">{attendancePermission(record)}</small>{/if}{#if record.corrected && record.source !== 'manual'}<small>Dikoreksi HR</small>{/if}</td><td>{#if record.source === 'manual'}<StatusPill label="Manual HR" tone="amber"/><small class="manual-source">GPS/selfie tidak diverifikasi</small><small class="source-reason">{record.correctionReason}</small>{:else}<span>Perangkat</span>{/if}</td><td><button class="btn btn-secondary" disabled={record.employeeId === $app.user?.id} title={record.employeeId === $app.user?.id ? 'Absensi sendiri harus dikoreksi Admin HR lain.' : 'Koreksi catatan absensi'} on:click={() => openCorrection(record)} aria-label={`Koreksi absensi ${displayName(record.employeeId)}`}><Icon name="edit" size={14}/>Koreksi</button></td></tr>{/each}</tbody></table></div>{:else}<EmptyState icon="clock" title="Tidak ada catatan pada filter ini" description="Ubah periode atau outlet untuk menampilkan kehadiran."/>{/if}
    {:else if tab === 'leave'}{#if leaves.length}<div class="table-wrap"><table><thead><tr><th>Karyawan</th><th>Jenis pengajuan</th><th>Tanggal</th><th>Status</th><th>Potongan</th><th>Keputusan</th></tr></thead><tbody>{#each leaves as request}<tr><td><strong>{displayName(request.employeeId)}</strong><small>{employeeNumber(request.employeeId)}</small></td><td>{leaveTypeLabel[request.type]}{#if request.startTime}<small>{request.startTime}–{request.endTime} WIB</small>{/if}</td><td>{dateLabel(request.startDate)}<small>sampai {dateLabel(request.endDate)}</small></td><td><StatusPill label={leaveStatusLabel[request.status]} tone={leaveTone(request.status)}/>{#if request.adjustment?.status === 'pending'}<small>Perubahan menunggu</small>{/if}</td><td>{request.status === 'approved' ? `${request.deductionDays} hari` : '—'}</td><td>{request.externalApproverName || (request.approverId ? displayName(request.approverId) : 'Belum diputuskan')}<small class="note">{request.note}</small></td></tr>{/each}</tbody></table></div>{:else}<EmptyState icon="calendar" title="Tidak ada pengajuan pada filter ini" description="Pengajuan cuti dan izin akan muncul setelah karyawan mengirimnya."/>{/if}
    {:else}{#if audits.length}<div class="audit-list">{#each audits as entry}<div class="audit-row"><span class="audit-symbol"><Icon name="edit" size={17}/></span><div><h3>{entry.action}</h3><p>{entry.detail}</p><small>{displayName(entry.actorId)} · {dateLabel(entry.at)} {timeLabel(entry.at)} WIB</small></div></div>{/each}</div>{:else}<EmptyState icon="file" title="Belum ada perubahan tercatat" description="Pendaftaran, keputusan pengajuan, dan koreksi tersimpan dalam riwayat ini."/>{/if}{/if}
    <div class="table-footer">{tab === 'attendance' ? attendance.length : tab === 'leave' ? leaves.length : audits.length} catatan · Waktu ditampilkan dalam WIB</div>
  </section>{#if tab === 'attendance'}<p class="footnote">Menit berizin dan tanpa izin dapat berada dalam satu catatan. Total aktual tetap dicatat; selisih bukan potongan otomatis. Sesi ≥12 jam perlu dikonfirmasi sebelum koreksi waktu sebenarnya.</p>{/if}<p class="footnote">CSV dapat dibuka di Excel. Foto selfie dan dokumen pribadi tidak disertakan dalam ekspor.</p>
{/if}

<Modal open={admin && correctionReview !== null} title="Tinjau koreksi absensi" description="Konfirmasi waktu sebenarnya sebelum memberi keputusan." onclose={() => correctionReview = null}>{#if correctionReview}<div class="original"><span><strong>{displayName(correctionReview.employeeId)} · {dateLabel(correctionReview.workDate)}</strong><br/>{shiftLabel(correctionReview.shift)} · {outletName(correctionReview.outletId)}<br/>Masuk: {dateLabel(correctionReview.proposedClockIn)} {timeLabel(correctionReview.proposedClockIn)} WIB<br/>Pulang: {correctionReview.proposedClockOut ? `${dateLabel(correctionReview.proposedClockOut)} ${timeLabel(correctionReview.proposedClockOut)}` : 'masih bekerja'}<br/>Alasan kasir: {correctionReview.reason}</span></div>{#if correctionReview.attendanceId}{@const original = $app.attendanceRecords.find(record => record.id === correctionReview?.attendanceId)}{#if original}<p class="hint">Catatan asli: {dateLabel(original.clockIn)} {timeLabel(original.clockIn)} – {original.clockOut ? `${dateLabel(original.clockOut)} ${timeLabel(original.clockOut)}` : 'belum pulang'} WIB · {shiftLabel(original.shift)}</p>{/if}{/if}{#if correctionReview.status === 'pending'}<label class="field">Alasan keputusan / sumber konfirmasi<textarea class="textarea" bind:value={correctionNote} minlength="3" rows="3" required></textarea></label><Feedback {message} error={failed}/><div class="form-actions"><button class="btn btn-secondary" disabled={saving || correctionReview.employeeId === $app.user?.id} on:click={() => decideCorrection(false)}>Tolak</button><button class="btn btn-primary" disabled={saving || correctionReview.employeeId === $app.user?.id || correctionNote.trim().length < 3} on:click={() => decideCorrection(true)}>Setujui koreksi</button></div>{:else}<p class="hint">Catatan keputusan: {correctionReview.decisionNote || '—'}</p>{/if}{/if}</Modal>

<Modal open={manualOpen} title="Catat absensi manual" description="Untuk kendala kamera, lokasi, atau absensi yang belum tercatat." onclose={() => { if (!saving) manualOpen = false; }}>
  <form on:submit|preventDefault={saveManual}>
    <div class="original manual-notice"><Icon name="info" size={17}/><span>Catatan manual <strong>tidak memiliki verifikasi GPS dan selfie</strong>. Masukkan waktu yang dikonfirmasi karyawan atau penanggung jawab. Alasan, sumber konfirmasi, dan pencatat disimpan dalam riwayat.</span></div>
    <label class="field">Kasir<select class="select" bind:value={manualEmployeeId} required><option value="" disabled>Pilih kasir</option>{#each manualCashiers as employee}<option value={employee.id}>{employee.fullName} — {employee.employeeNumber}</option>{/each}</select></label>
    {#if manualEmployee}<p class="hint">Penempatan: {outletName(manualEmployee.outletId)}</p>{/if}
    <label class="field">Shift<select class="select" bind:value={manualShift} required><option value="morning">Pagi</option><option value="afternoon">Sore</option>{#if manualEmployee?.canMiddleShift}<option value="middle">Middle</option>{/if}</select></label>
    <div class="form-grid"><label class="field">Clock in (WIB)<input class="input" type="datetime-local" bind:value={manualIn} required/></label><label class="field">Clock out (WIB)<input class="input" type="datetime-local" bind:value={manualOut} min={manualIn}/></label></div>
    <p class="hint">Biarkan clock out kosong jika kasir masih bekerja. Waktu yang dicatat harus sudah terjadi.</p>
    <label class="field">Alasan dan sumber konfirmasi<textarea class="textarea" rows="3" bind:value={manualReason} required placeholder="Contoh: kamera bermasalah; jam masuk dikonfirmasi kasir melalui WhatsApp."></textarea></label>
    <Feedback {message} error={failed}/>
    <div class="form-actions"><button class="btn btn-secondary" type="button" disabled={saving} on:click={() => manualOpen = false}>Batal</button><button class="btn btn-primary" type="submit" disabled={saving || !manualEmployee}>{saving ? 'Menyimpan…' : 'Simpan absensi manual'}</button></div>
  </form>
</Modal>

<Modal open={selected !== null} title="Koreksi kehadiran" description={selected ? `${displayName(selected.employeeId)} · ${outletName(selected.outletId)}` : ''} onclose={() => selected = null}>
  {#if selected}<form on:submit|preventDefault={saveCorrection}><div class="original"><Icon name="info" size={17}/><span>Catatan asli tetap tersimpan dalam riwayat. Gunakan koreksi untuk lupa clock out atau kesalahan pencatatan.</span></div><label class="field">Shift<select class="select" bind:value={correctedShift}><option value="morning">Pagi</option><option value="afternoon">Sore</option><option value="middle">Middle</option></select></label><div class="form-grid"><label class="field">Clock in (WIB)<input class="input" type="datetime-local" bind:value={correctedIn} required/></label><label class="field">Clock out (WIB)<input class="input" type="datetime-local" bind:value={correctedOut}/></label></div><p class="hint">Biarkan clock out kosong jika sesi kerja masih berlangsung. Untuk lupa clock out, konfirmasi dan masukkan waktu pulang yang sebenarnya.</p><label class="field">Alasan koreksi<textarea class="textarea" rows="3" bind:value={reason} required placeholder="Jelaskan alasan dan sumber konfirmasi…"></textarea></label><Feedback {message} error={failed}/><div class="form-actions"><button class="btn btn-secondary" type="button" on:click={() => selected = null}>Batal</button><button class="btn btn-primary" type="submit" disabled={saving}>{saving ? 'Menyimpan…' : 'Simpan koreksi'}</button></div></form>{/if}
</Modal>

<style>
.audit-filter{display:flex;align-items:center;justify-content:space-between;gap:.7rem;font-size:.74rem;padding:.8rem 1.2rem;border-bottom:1px solid var(--border);color:var(--ink)}.audit-filter .btn{font-size:.68rem}@media(max-width:900px){.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}}td :global(.pill){margin-top:.25rem}

.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:1rem;margin-bottom:1.5rem}.report-panel{padding:0;overflow:hidden}.tabs{display:flex;gap:.5rem;padding:0 1.2rem;border-bottom:1px solid var(--border);overflow-x:auto}.tabs button{white-space:nowrap;border:0;border-bottom:2px solid transparent;background:transparent;padding:1.2rem .65rem;font-size:.78rem;color:var(--muted);cursor:pointer}.tabs button.active{color:var(--muted);border-bottom-color:#ad9e6c}.filters{display:grid;grid-template-columns:1fr 1fr 1.1fr 1.1fr 1.2fr auto;gap:.75rem;padding:1.2rem;border-bottom:1px solid var(--border);align-items:end}.filters :global(.field){font-size:.67rem}.filters input,.filters select{font-size:.74rem;padding:.65rem}.reset{border:1px solid var(--border);background:#faf7ef;border-radius:8px;color:var(--muted);width:37px;height:37px;display:grid;place-items:center;cursor:pointer}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;text-align:left;white-space:nowrap}th{font-size:.62rem;text-transform:uppercase;font-weight:600;letter-spacing:.055em;color:var(--muted);background:#fdfcf8;padding:1rem 1.15rem}td{padding:1rem 1.15rem;font-size:.75rem;color:var(--muted);border-bottom:1px solid var(--border)}td strong{font-size:.78rem;font-weight:600}td small{display:block;font-size:.63rem;color:var(--muted);margin-top:.4rem}.note{max-width:180px;overflow:hidden;text-overflow:ellipsis}td .btn{font-size:.65rem;padding:.45rem .65rem;white-space:nowrap}.table-footer{padding:1rem 1.2rem;font-size:.65rem;color:var(--muted)}.footnote{font-size:.66rem;color:var(--muted);margin:1.1rem .2rem}.audit-row{display:flex;gap:.85rem;padding:1.2rem;border-bottom:1px solid var(--border)}.audit-symbol{display:grid;place-items:center;width:34px;height:34px;border-radius:10px;background:#f7f4e8;color:var(--muted);flex-shrink:0}.audit-row h3{font-size:.8rem;color:var(--muted);font-weight:600;margin:0 0 .4rem}.audit-row p{font-size:.73rem;color:var(--muted);line-height:1.7;margin:0 0 .4rem}.audit-row small{font-size:.63rem;color:var(--muted)}.original{display:flex;gap:.65rem;font-size:.76rem;line-height:1.7;background:#f8f5eb;color:var(--muted);padding:1rem;border-radius:10px;margin-bottom:1.2rem}.original :global(svg){flex-shrink:0;margin-top:.2rem}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:.9rem;margin-top:1rem}.hint{font-size:.68rem;line-height:1.7;color:var(--muted);margin:.8rem 0 1.2rem}.form-actions{display:flex;justify-content:flex-end;gap:.6rem;border-top:1px solid var(--border);margin-top:1.2rem;padding-top:1.2rem}@media(max-width:900px){.filters{grid-template-columns:1fr 1fr}.filters>label:nth-child(4){grid-column:auto}.reset{grid-column:1/-1;width:100%}}@media(max-width:600px){.metrics{gap:.5rem}.metrics :global(.metric){padding:1rem .8rem}.metrics :global(.top){font-size:.65rem}.metrics :global(.icon){display:none}.metrics :global(strong){font-size:1.35rem}.metrics :global(p){font-size:.61rem}.filters{padding:1rem;gap:.7rem}.tabs{padding:0 .7rem;gap:.25rem}.tabs button{padding:1rem .5rem;font-size:.7rem}.form-grid{grid-template-columns:1fr}th,td{padding:.9rem 1rem}.audit-row{padding:1rem}.audit-row h3{font-size:.75rem}}
  .tabs { padding: .6rem 1.2rem; gap: .65rem; }
  .tabs button { min-height: 44px; border-bottom: 0; padding: .75rem .9rem; border-radius: 12px; }
  .tabs button.active { color: var(--accent); background: var(--surface); box-shadow: var(--inset); font-weight: 600; }
  .reset { background: var(--surface); border-color: #e0d1a1; box-shadow: var(--raised-sm); color: var(--accent); border-radius: 12px; min-width: 44px; min-height: 46px; }
  .reset:active { box-shadow: var(--inset); }
  th { background: #f1ebd6; }
  td { color: #5f5535; }

  .audit-symbol { background: var(--surface); color: var(--accent); box-shadow: var(--raised-sm); border-radius: 12px; }
  .audit-row h3 { color: var(--ink); }
  .original { background: var(--surface); color: #655b39; border: 1px solid #ffffff9c; box-shadow: var(--inset); border-radius: 14px; }
  @media (max-width: 600px) { .tabs { padding: .5rem .7rem; gap: .25rem; } .tabs button { padding: .7rem .6rem; } }
  .permission-note { color: #5c512e; max-width: 185px; white-space: normal; line-height: 1.6; }
